import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.NIGIbcGl.js";const u=JSON.parse('{"title":"Organization Reports (B2B self-service)","description":"","frontmatter":{},"headers":[],"relativePath":"admin/reports/organization.md","filePath":"admin/reports/organization.md"}'),s={name:"admin/reports/organization.md"};function r(n,e,i,c,p,l){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="organization-reports-b2b-self-service" tabindex="-1">Organization Reports (B2B self-service) <a class="header-anchor" href="#organization-reports-b2b-self-service" aria-label="Permalink to &quot;Organization Reports (B2B self-service)&quot;">​</a></h1><p>Reporting endpoints scoped to the <strong>caller&#39;s own organization</strong>. Unlike the admin financial reports (which aggregate across the whole platform), these are consumed by <strong>B2B organization users</strong> to see their own bookings, revenue, wallet, refunds, and tax.</p><p>The organization is resolved from the authenticated user&#39;s <code>organizationId</code> — there is no <code>organizationId</code> query parameter and no cross-organization access. A user not associated with an organization gets <code>403 Forbidden</code>.</p><blockquote><p><strong>Tag note.</strong> In Swagger these routes share the <strong><code>4. Admin - Reports</code></strong> tag with the admin hub, but the access role is <strong>B2B</strong>, not ADMIN — see <a href="#access">Access</a>.</p></blockquote><hr><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Base path</strong></td><td><code>/api/v1/reports/organization</code></td></tr><tr><td><strong>Auth</strong></td><td><code>AuthGuard(&#39;jwt&#39;)</code> — Bearer token required</td></tr><tr><td><strong>Role</strong></td><td><code>B2B</code> (<code>@Roles(UserRole.B2B)</code>)</td></tr><tr><td><strong>Scope</strong></td><td>The caller&#39;s own organization (<code>req.user.organizationId</code>)</td></tr></tbody></table><p><code>403 Forbidden</code> — <code>&quot;User is not associated with an organization&quot;</code> — when the authenticated user has no <code>organizationId</code>.</p><hr><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Summary</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/reports/organization/dashboard</code></td><td>KPI summary for the org</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/reports/organization/revenue</code></td><td>Revenue report (+ chart series)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/reports/organization/transactions</code></td><td>Transactions report (paginated)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/reports/organization/wallets</code></td><td>Wallet balances + activity</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/reports/organization/refunds</code></td><td>Refunds report (paginated)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/reports/organization/tax</code></td><td>Tax report (+ chart series)</td></tr></tbody></table><hr><h2 id="common-query-parameters" tabindex="-1">Common query parameters <a class="header-anchor" href="#common-query-parameters" aria-label="Permalink to &quot;Common query parameters&quot;">​</a></h2><p>All endpoints except <code>wallets</code> accept a date range. <code>transactions</code> and <code>refunds</code> additionally accept pagination. <code>revenue</code> and <code>tax</code> accept a chart grouping.</p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Applies to</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>preset</code></td><td>enum</td><td>dashboard, revenue, transactions, refunds, tax</td><td><code>THIS_MONTH</code></td><td><code>TODAY</code>, <code>YESTERDAY</code>, <code>LAST_7_DAYS</code>, <code>LAST_30_DAYS</code>, <code>THIS_MONTH</code>, <code>LAST_MONTH</code>, <code>CUSTOM</code></td></tr><tr><td><code>from</code></td><td>ISO date</td><td>same</td><td>—</td><td>Start date (e.g. <code>2026-01-01</code>). Used with <code>preset=CUSTOM</code>.</td></tr><tr><td><code>to</code></td><td>ISO date</td><td>same</td><td>—</td><td>End date (e.g. <code>2026-01-31</code>). Used with <code>preset=CUSTOM</code>.</td></tr><tr><td><code>groupBy</code></td><td>enum</td><td>revenue (<code>day</code>), tax (<code>month</code>)</td><td>per-endpoint</td><td><code>day</code>, <code>week</code>, <code>month</code> — chart bucket size</td></tr><tr><td><code>page</code></td><td>number</td><td>transactions, refunds</td><td><code>1</code></td><td>Page number</td></tr><tr><td><code>limit</code></td><td>number</td><td>transactions, refunds</td><td><code>20</code></td><td>Items per page</td></tr></tbody></table><blockquote><p><code>wallets</code> takes <strong>no</strong> query parameters — it returns the current wallet snapshot for the organization.</p></blockquote><hr><h2 id="endpoint-detail" tabindex="-1">Endpoint detail <a class="header-anchor" href="#endpoint-detail" aria-label="Permalink to &quot;Endpoint detail&quot;">​</a></h2><h3 id="get-dashboard" tabindex="-1"><code>GET /dashboard</code> <a class="header-anchor" href="#get-dashboard" aria-label="Permalink to &quot;`GET /dashboard`&quot;">​</a></h3><p>KPI summary card data for the selected period.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/reports/organization/dashboard?preset=THIS_MONTH</span></span>\n<span class="line"><span>Authorization: Bearer &lt;b2b-jwt&gt;</span></span></code></pre></div><p>Returns <code>{ period: { from, to }, kpi: { ... } }</code>.</p><h3 id="get-revenue" tabindex="-1"><code>GET /revenue</code> <a class="header-anchor" href="#get-revenue" aria-label="Permalink to &quot;`GET /revenue`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/reports/organization/revenue?preset=LAST_30_DAYS&amp;groupBy=day</span></span></code></pre></div><p>Revenue summary, breakdown by payment method and route, and a chart series bucketed by <code>groupBy</code> (default <code>day</code>).</p><h3 id="get-transactions" tabindex="-1"><code>GET /transactions</code> <a class="header-anchor" href="#get-transactions" aria-label="Permalink to &quot;`GET /transactions`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/reports/organization/transactions?preset=THIS_MONTH&amp;page=1&amp;limit=20</span></span></code></pre></div><p>Paginated transaction list plus status/method counts and a chart series. Response includes <code>totalPages</code> and <code>page</code>.</p><h3 id="get-wallets" tabindex="-1"><code>GET /wallets</code> <a class="header-anchor" href="#get-wallets" aria-label="Permalink to &quot;`GET /wallets`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/reports/organization/wallets</span></span></code></pre></div><p>Wallet balances and activity for the organization. No date range.</p><h3 id="get-refunds" tabindex="-1"><code>GET /refunds</code> <a class="header-anchor" href="#get-refunds" aria-label="Permalink to &quot;`GET /refunds`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/reports/organization/refunds?preset=THIS_MONTH&amp;page=1&amp;limit=20</span></span></code></pre></div><p>Paginated refunds plus summary and policy breakdown. Response includes <code>totalPages</code> and <code>page</code>.</p><h3 id="get-tax" tabindex="-1"><code>GET /tax</code> <a class="header-anchor" href="#get-tax" aria-label="Permalink to &quot;`GET /tax`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/reports/organization/tax?preset=THIS_MONTH&amp;groupBy=month</span></span></code></pre></div><p>Tax summary, breakdown by route, and a chart series bucketed by <code>groupBy</code> (default <code>month</code>).</p><hr><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://&lt;host&gt;/api/v1/reports/organization/revenue?preset=THIS_MONTH&amp;groupBy=day&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;b2b-jwt&gt;&quot;</span></span></code></pre></div><hr><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Controller: <code>src/modules/reports/org-reports.controller.ts</code></li><li>Service: <code>src/modules/reports/reports.service.ts</code></li><li>DTOs: <code>src/modules/reports/dto/</code> (<code>date-range.dto.ts</code>, <code>*-response.dto.ts</code>)</li></ul>',43)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
